<?php
require '../config/db.php'; require '../config/auth.php'; require_role('admin','login.php'); $u=current_user();
$parishTz=new DateTimeZone('Asia/Manila'); $parishNow=new DateTimeImmutable('now',$parishTz); $parishToday=$parishNow->format('Y-m-d'); $parishMonth=$parishNow->format('Y-m');
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf(); $a=$_POST['action']??'add'; $id=(int)($_POST['id']??0);
    if($a==='delete'&&$id){
        $pdo->prepare('DELETE FROM events WHERE id=?')->execute([$id]);
        log_activity($pdo,$u['id'],'Deleted event','Event #'.$id); flash('success','Event deleted.');
    }else{
        $title=trim($_POST['title']??''); $date=$_POST['event_date']??'';
        $startTime=trim($_POST['start_time']??''); $endTime=trim($_POST['end_time']??'');
        if(!$title||!$date){ flash('error','Title and event date are required.'); }
        elseif(($startTime&&!$endTime)||(!$startTime&&$endTime)){ flash('error','Enter both a start and end time so booking availability can be protected.'); }
        elseif($startTime&&$endTime&&$endTime<=$startTime){ flash('error','Event end time must be later than its start time.'); }
        else{
            $conflict=null;
            if($startTime&&$endTime){
                $q=$pdo->prepare("SELECT a.reference_no,a.start_time,a.end_time,s.name service_name FROM appointments a JOIN services s ON s.id=a.service_id WHERE a.appointment_date=? AND a.status IN ('pending','approved') AND a.start_time < ? AND a.end_time > ? ORDER BY a.start_time LIMIT 1");
                $q->execute([$date,$endTime,$startTime]); $conflict=$q->fetch();
            }
            if($conflict){
                flash('error','Cannot add this event because it overlaps appointment '.$conflict['reference_no'].' ('.$conflict['service_name'].') from '.date('g:i A',strtotime($conflict['start_time'])).' to '.date('g:i A',strtotime($conflict['end_time'])).'.');
            }else{
                $pdo->prepare('INSERT INTO events(title,description,event_date,start_time,end_time,category) VALUES(?,?,?,?,?,?)')->execute([$title,trim($_POST['description']??''),$date,$startTime?:null,$endTime?:null,trim($_POST['category']??'')]);
                log_activity($pdo,$u['id'],'Added event',$title); flash('success','Event added. Its scheduled time is now blocked from parishioner bookings.');
            }
        }
    }
    redirect('event-calendar.php?month='.urlencode($_GET['month']??$parishMonth));
}
$month=$_GET['month']??$parishMonth; if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=$parishMonth;
$first=$month.'-01'; $days=(int)date('t',strtotime($first)); $offset=(int)date('N',strtotime($first)); $start=$first; $end=date('Y-m-t',strtotime($first));
$s=$pdo->prepare("SELECT * FROM events WHERE event_date BETWEEN ? AND ? ORDER BY event_date,start_time,title");$s->execute([$start,$end]);$all=$s->fetchAll();$ev=[];foreach($all as $r)$ev[$r['event_date']][]=$r;
$s=$pdo->prepare("SELECT a.id,a.reference_no,a.appointment_date,a.start_time,a.end_time,a.status,s.name service_name,r.name resource_name,u.full_name person,u.email FROM appointments a JOIN services s ON s.id=a.service_id JOIN users u ON u.id=a.user_id LEFT JOIN resources r ON r.id=a.resource_id WHERE a.appointment_date BETWEEN ? AND ? AND a.status='approved' ORDER BY a.appointment_date,a.start_time");$s->execute([$start,$end]);$approved=$s->fetchAll();$ap=[];foreach($approved as $r)$ap[$r['appointment_date']][]=$r;
$prev=date('Y-m',strtotime($first.' -1 month'));$next=date('Y-m',strtotime($first.' +1 month'));$today=$parishToday;
function tlabel($start,$end=null){if(!$start)return 'Time not specified';$v=date('g:i A',strtotime($start));if($end)$v.=' – '.date('g:i A',strtotime($end));return $v;}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Event Calendar</title><link rel="stylesheet" href="../assets/css/style.css"><style>
.calendar-actions{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px}.calendar-nav{display:flex;gap:8px;flex-wrap:wrap}.calendar-add{margin-left:auto;white-space:nowrap}.calendar-grid .day{position:relative;min-height:125px;cursor:pointer;transition:.18s ease}.calendar-grid .day:not(.empty):hover{border-color:#9b8d79;box-shadow:0 7px 18px rgba(26,35,50,.08);transform:translateY(-1px)}.calendar-grid .day.is-today{background:#f1eadf;border-color:#1a2332}.cal-count{position:absolute;right:8px;top:8px;font-size:10px;padding:4px 7px;border-radius:999px;background:#1a2332;color:#fff}.event-dot{display:block;margin-top:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.event-dot.parish-event{background:#e5ece8}.event-dot.booking{background:#eee6d8}.calendar-key{display:flex;gap:16px;flex-wrap:wrap;margin-bottom:14px;font-size:12px;color:#77736c}.calendar-key span{display:flex;align-items:center;gap:6px}.calendar-key i{width:10px;height:10px;border-radius:50%;background:#e5ece8;border:1px solid #c9d4ce}.calendar-key i.booking{background:#eee6d8;border-color:#d9cbb6}.day-modal-backdrop{position:fixed;inset:0;background:rgba(18,24,33,.48);display:none;align-items:center;justify-content:center;padding:18px;z-index:1000}.day-modal-backdrop.open{display:flex}.day-modal{width:min(680px,100%);max-height:85vh;overflow:auto;background:#fffdf9;border:1px solid #e5dccf;border-radius:22px;padding:24px;box-shadow:0 24px 70px rgba(0,0,0,.22)}.day-modal-head{display:flex;justify-content:space-between;gap:16px;align-items:start}.day-modal-head h2{margin:3px 0 0}.day-close{border:0;background:#f1eadf;width:38px;height:38px;border-radius:50%;cursor:pointer;font-size:20px}.schedule-item{padding:14px 0;border-top:1px solid #eee5d9}.schedule-item:first-child{border-top:0}.schedule-meta{display:flex;gap:8px;flex-wrap:wrap;margin:6px 0;color:#6f6a63;font-size:13px}.schedule-type{font-size:10px;text-transform:uppercase;letter-spacing:.08em;font-weight:700;background:#e5ece8;padding:4px 7px;border-radius:999px}.schedule-type.booking{background:#eee6d8}.schedule-item p{margin:7px 0 0}.empty-schedule{padding:20px 0;color:#77736c}.today-number{display:inline-flex;align-items:center;justify-content:center;width:31px;height:31px;border-radius:50%;background:#1a2332;color:#fff}
.schedule-layout{display:grid;grid-template-columns:minmax(300px,380px) minmax(0,1fr);gap:18px;align-items:start}.schedule-calendar{min-width:0}.events-panel{min-width:0}.events-panel-head{display:flex;align-items:end;justify-content:space-between;gap:12px;margin-bottom:14px}.events-panel-head h2{margin:0}.event-list{display:grid;gap:10px;margin-top:14px}.event-card{border:1px solid #e8dfd2;border-radius:16px;padding:14px;background:#fffdf9}.event-card-top{display:flex;justify-content:space-between;gap:10px;align-items:start}.event-card h3{margin:0 0 4px;font-size:16px}.event-card .event-time{font-weight:700;font-size:13px}.event-card .event-category{font-size:12px;color:#77736c;margin-top:3px}.event-card .event-desc{font-size:13px;color:#6f6a63;margin:8px 0 0}.event-card .event-actions{margin-top:10px}.add-event-modal{position:fixed;inset:0;background:rgba(18,24,33,.48);display:none;align-items:center;justify-content:center;padding:18px;z-index:1100}.add-event-modal.open{display:flex}.add-event-dialog{width:min(720px,100%);max-height:90vh;overflow:auto;background:#fffdf9;border:1px solid #e5dccf;border-radius:22px;padding:24px;box-shadow:0 24px 70px rgba(0,0,0,.22)}.add-event-head{display:flex;align-items:start;justify-content:space-between;gap:16px;margin-bottom:18px}.add-event-head h2{margin:3px 0 0}.topbar-actions{display:flex;align-items:center;gap:12px}.topbar-actions .muted{white-space:nowrap}.events-panel .live-filter-bar{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:end}.events-panel .live-search-field{grid-column:1/-1}.events-panel .live-filter-meta{align-self:center}.events-panel .live-empty-card{padding:18px;border:1px dashed #ddd2c3;border-radius:14px;color:#77736c;text-align:center}
@media(max-width:1050px){.schedule-layout{grid-template-columns:320px minmax(0,1fr)}}
@media(max-width:900px){.schedule-layout{display:flex;flex-direction:column}.schedule-calendar{order:1;width:100%}.events-panel{order:2;width:100%}.topbar-actions .muted{display:none}}
@media(max-width:700px){.calendar-actions{align-items:stretch}.calendar-nav{flex:1}.calendar-nav .btn{flex:1;text-align:center;padding-left:10px;padding-right:10px}.calendar-add{margin-left:0}.calendar-grid .day{min-height:88px}.event-dot{font-size:10px}.cal-count{position:static;float:right}.day-modal{padding:18px;border-radius:18px}}
</style></head><body><div class="shell"><?php include 'includes/sidebar.php'?><main class="main"><header class="topbar"><div><button class="btn light mobile-toggle" data-nav-toggle>☰</button><div class="eyebrow">Parish schedule</div><h1><?=date('F Y',strtotime($first))?></h1></div></header>
<?php if($m=flash('success')):?><div class="notice"><?=e($m)?></div><?php endif;if($m=flash('error')):?><div class="notice error"><?=e($m)?></div><?php endif;?>
<div class="calendar-actions"><div class="calendar-nav"><a class="btn light" href="?month=<?=e($prev)?>">← Previous</a><a class="btn" href="?month=<?=e($parishMonth)?>">Today</a><a class="btn light" href="?month=<?=e($next)?>">Next →</a></div><button class="btn calendar-add" type="button" id="openAddEvent">+ Add Event</button></div>
<div class="schedule-layout"><section class="card events-panel" data-live-scope><div class="events-panel-head"><div><div class="eyebrow">This month</div><h2>Parish events</h2></div><span class="muted"><?=count($all)?> event<?=count($all)===1?'':'s'?></span></div><div class="live-filter-bar"><label class="field live-search-field">Search events<input class="search" type="search" data-live-search placeholder="Search title, category or date..."></label><button type="button" class="btn light" data-live-clear>Clear</button><span class="live-filter-meta" data-live-count></span></div><div class="event-list" data-live-list><div data-live-empty class="live-empty-card" hidden>No events match your search.</div><?php foreach($all as $x):?><article class="event-card" data-live-item data-search="<?=e(strtolower($x['title'].' '.($x['category']??'').' '.$x['event_date'].' '.($x['description']??'')))?>"><div class="event-card-top"><div><h3><?=e($x['title'])?></h3><div class="event-time"><?=date('M j',strtotime($x['event_date']))?> · <?=e(tlabel($x['start_time'],$x['end_time']))?></div><?php if(!empty($x['category'])):?><div class="event-category"><?=e($x['category'])?></div><?php endif?></div></div><?php if(!empty($x['description'])):?><p class="event-desc"><?=e($x['description'])?></p><?php endif?><div class="event-actions"><form method="post" onsubmit="return confirm('Delete this event?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn danger small">Delete</button></form></div></article><?php endforeach?></div></section><div class="schedule-calendar"><section class="card"><div class="calendar-key"><span><i></i>Parish event</span><span><i class="booking"></i>Approved appointment</span><span>Click any day to view its schedule</span></div><div class="calendar-grid"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $d):?><b class="muted" style="text-align:center"><?=$d?></b><?php endforeach;for($i=1;$i<$offset;$i++):?><div class="day empty"></div><?php endfor;for($d=1;$d<=$days;$d++):$date=$month.'-'.str_pad((string)$d,2,'0',STR_PAD_LEFT);$count=count($ev[$date]??[])+count($ap[$date]??[]);?><div class="day <?=$date===$today?'is-today':''?>" data-date="<?=e($date)?>"><strong class="<?=$date===$today?'today-number':''?>"><?=$d?></strong><?php if($count):?><span class="cal-count"><?=$count?></span><?php endif?><?php foreach(array_slice($ev[$date]??[],0,2) as $x):?><span class="event-dot parish-event"><?=e(($x['start_time']?date('g:i A',strtotime($x['start_time'])).' · ':'').$x['title'])?></span><?php endforeach?><?php foreach(array_slice($ap[$date]??[],0,max(0,2-count(array_slice($ev[$date]??[],0,2)))) as $x):?><span class="event-dot booking"><?=e(date('g:i A',strtotime($x['start_time'])).' · '.$x['service_name'])?></span><?php endforeach?><?php if($count>2):?><span class="muted" style="font-size:11px">+<?=$count-2?> more</span><?php endif?></div><?php endfor?></div></section></div></div>
<div class="add-event-modal" id="addEventModal" aria-hidden="true"><div class="add-event-dialog" role="dialog" aria-modal="true" aria-labelledby="addEventTitle"><div class="add-event-head"><div><div class="eyebrow">New parish schedule</div><h2 id="addEventTitle">Add event</h2></div><button class="day-close" type="button" id="closeAddEvent" aria-label="Close">×</button></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="add"><label class="field full">Title<input name="title" required autofocus></label><label class="field">Date<input type="date" name="event_date" required></label><label class="field">Category<input name="category" placeholder="Mass, meeting, feast..."></label><label class="field">Start<input type="time" name="start_time"></label><label class="field">End<input type="time" name="end_time"></label><label class="field full">Description<textarea name="description"></textarea></label><div class="full" style="display:flex;justify-content:flex-end;gap:8px"><button class="btn light" type="button" id="cancelAddEvent">Cancel</button><button class="btn">Add event</button></div></form></div></div>
<div class="day-modal-backdrop" id="dayModal" aria-hidden="true"><div class="day-modal" role="dialog" aria-modal="true"><div class="day-modal-head"><div><div class="eyebrow">Daily schedule</div><h2 id="dayModalTitle"></h2></div><button class="day-close" type="button" aria-label="Close">×</button></div><div id="dayModalBody"></div></div></div>
</main></div><script src="../assets/js/script.js"></script><script>
const addEventModal=document.getElementById('addEventModal'),openAddEvent=document.getElementById('openAddEvent');function showAddEvent(){addEventModal.classList.add('open');addEventModal.setAttribute('aria-hidden','false');const dateInput=addEventModal.querySelector('input[name=event_date]');if(!dateInput.value)dateInput.value='<?=e($today)?>';setTimeout(()=>addEventModal.querySelector('input[name=title]').focus(),50)}function hideAddEvent(){addEventModal.classList.remove('open');addEventModal.setAttribute('aria-hidden','true')}openAddEvent.addEventListener('click',showAddEvent);document.getElementById('closeAddEvent').addEventListener('click',hideAddEvent);document.getElementById('cancelAddEvent').addEventListener('click',hideAddEvent);addEventModal.addEventListener('click',e=>{if(e.target===addEventModal)hideAddEvent()});
const scheduleData=<?=json_encode(array_reduce(array_unique(array_merge(array_keys($ev),array_keys($ap))),function($out,$date)use($ev,$ap){$out[$date]=[];foreach($ev[$date]??[] as $x)$out[$date][]=['type'=>'event','title'=>$x['title'],'time'=>tlabel($x['start_time'],$x['end_time']),'category'=>$x['category']?:'Parish event','description'=>$x['description']?:''];foreach($ap[$date]??[] as $x)$out[$date][]=['type'=>'booking','title'=>$x['service_name'],'time'=>tlabel($x['start_time'],$x['end_time']),'category'=>'Approved appointment','description'=>$x['reference_no'].' · '.$x['person'].($x['resource_name']?' · '.$x['resource_name']:'') ,'url'=>'appointments.php?search='.rawurlencode($x['reference_no'])];return $out;},[]),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;
const modal=document.getElementById('dayModal'), title=document.getElementById('dayModalTitle'), body=document.getElementById('dayModalBody');
function esc(v){const d=document.createElement('div');d.textContent=v??'';return d.innerHTML}function openDay(date){const rows=scheduleData[date]||[];title.textContent=new Date(date+'T00:00:00').toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'});body.innerHTML=rows.length?rows.map(x=>`<div class="schedule-item"><span class="schedule-type ${x.type==='booking'?'booking':''}">${x.type==='booking'?'Approved appointment':'Parish event'}</span><h3>${esc(x.title)}</h3><div class="schedule-meta"><b>${esc(x.time)}</b><span>${esc(x.category)}</span></div>${x.description?`<p>${esc(x.description)}</p>`:''}${x.url?`<p><a class="btn light small" href="${x.url}">Open appointment list</a></p>`:''}</div>`).join(''):'<div class="empty-schedule">No parish events or approved appointments scheduled for this day.</div>';modal.classList.add('open');modal.setAttribute('aria-hidden','false')}
function manilaToday(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const v={};parts.forEach(p=>v[p.type]=p.value);return `${v.year}-${v.month}-${v.day}`}function syncTodayMarker(){const actual=manilaToday();document.querySelectorAll('.calendar-grid .day[data-date]').forEach(day=>{const yes=day.dataset.date===actual;day.classList.toggle('is-today',yes);const n=day.querySelector('strong');if(n)n.classList.toggle('today-number',yes)});const todayLink=document.querySelector('.calendar-nav a:nth-child(2)');if(todayLink)todayLink.href='?month='+actual.slice(0,7)}syncTodayMarker();setInterval(syncTodayMarker,60000);
document.querySelectorAll('.calendar-grid .day[data-date]').forEach(d=>d.addEventListener('click',()=>openDay(d.dataset.date)));function closeDay(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true')}modal.querySelector('.day-close').addEventListener('click',closeDay);modal.addEventListener('click',e=>{if(e.target===modal)closeDay()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDay();hideAddEvent()}});
</script></body></html>
